import sys
from collections import deque

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        print([])
        return

    n = int(data[0])
    m = int(data[1])

    if n == 0:
        print([])
        return

    adj = [[] for _ in range(n)]
    in_degree = [0] * n

    idx = 2
    for _ in range(m):
        a = int(data[idx])
        b = int(data[idx + 1])
        idx += 2
        adj[b].append(a)
        in_degree[a] += 1

    queue = deque()
    for i in range(n):
        if in_degree[i] == 0:
            queue.append(i)

    result = []
    while queue:
        node = queue.popleft()
        result.append(node)
        for neighbor in adj[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    if len(result) != n:
        print([])
    else:
        print(result)

if __name__ == "__main__":
    main()
